import sys

class Pair:
    __slots__ = ('first', 'second')
    def __init__(self, first, second):
        self.first = first
        self.second = second
    def __eq__(self, other):
        return isinstance(other, Pair) and self.first == other.first and self.second == other.second
    def compare_with(self, other):
        return "The pairs are equal." if self == other else "The pairs are not equal."

def solve() -> None:
    lines = [line.rstrip('\n') for line in sys.stdin if line.strip() != '']
    i = 0
    results = []
    while i + 3 < len(lines):
        try:
            a = int(lines[i].strip())
            b = lines[i + 1]
            c = int(lines[i + 2].strip())
            d = lines[i + 3]
        except Exception:
            break
        pair1 = Pair(a, b)
        pair2 = Pair(c, d)
        results.append(pair1.compare_with(pair2))
        i += 4
    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
